const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const etna = ee.Geometry.Point(15.00, 37.75); // Approximate coordinates of Mount Etna
  const buffer_radius = 50000; // 50 km buffer around Etna
  const etna_area = etna.buffer(buffer_radius);

  // Local time (CET, UTC+1) 1:37 am on Feb 23, 2021
  // UTC time: 00:37 UTC on Feb 23, 2021
  // VIIRS overpass times are not exactly at 00:37 UTC, so we'll filter for the full day to catch any relevant passes.
  const start_date = '2021-02-23T00:00:00';
  const end_date = '2021-02-23T23:59:59'; // Full day to capture any VIIRS pass

  // 2. Data Acquisition
  // VIIRS Day/Night Band (DNB) is suitable for nighttime visible detection.
  // Although not directly 'visible' in the sense of a daytime plume, DNB can detect active fires/hot spots.
  let collection = ee.ImageCollection('NOAA/VIIRS/DNB/V2')
    .filterDate(start_date, end_date)
    .filterBounds(etna_area)
    .select('radiance');

  const initial_size = await collection.size().getInfo();
  if (initial_size === 0) {
    console.log("No VIIRS DNB images found for Mount Etna on Feb 23, 2021.");
    console.log("C1");
    return;
  }
  console.log(`VIIRS DNB images found: ${initial_size}`);

  // It's possible to get multiple images over the area on a single day.
  // We'll take the median to represent the 'average' conditions, which should highlight persistent anomalies.
  // A single eruption event might be better seen in a specific image, but median can help reduce noise.
  let image = collection.median();

  // Check if the image is empty after reduction
  const bandNames = await image.bandNames().getInfo();
  if (bandNames.length === 0) {
    console.log("No valid bands after collection reduction (median).");
    console.log("C3"); // Indicates an issue in image creation from collection
    return;
  }

  // Define a threshold for detecting a plume/hotspot.
  // VIIRS DNB radiance values for clouds are typically low (0-5 nW/cm^2/sr).
  // Fires/hotspots can have significantly higher radiance values, sometimes hundreds or thousands.
  // Given it's a "volcanic plume visible", we're looking for an anomaly.
  const radiance_threshold = 10; // nW/cm^2/sr - this threshold might need adjustment based on typical plume radiance

  // Masking based on radiance to identify potential plume areas
  let plume_mask = image.gt(radiance_threshold);
  let plume_pixels = image.updateMask(plume_mask);

  // Calculate the total number of 'plume' pixels within the analysis area
  const count_reducer = ee.Reducer.count();
  const plume_pixel_count = await plume_pixels.reduceRegion({
    reducer: count_reducer,
    geometry: etna_area,
    scale: 750, // VIIRS DNB resolution is ~750m at nadir
    maxPixels: 1e9
  }).get('radiance').getInfo();

  if (plume_pixel_count === null || plume_pixel_count === 0) {
    console.log(`No significant radiance detected above threshold (${radiance_threshold}) within 50km of Etna.`);
    console.log("No C2: No valid pixels identified as plume after thresholding.");
    console.log("B"); // No plume detected
    return;
  }
  console.log(`Potential plume pixels detected: ${plume_pixel_count}`);

  // 3. Determine plume direction
  // Find the centroid of the detected plume pixels.
  // If multiple plumes, this will give a combined centroid.
  // If the centroid is significantly to the west of Etna, then it went to the western side.
  let plume_centroid_obj = await plume_pixels.reduceRegion({
    reducer: ee.Reducer.mean(), // Using mean just to get a value, actual centroid calculation is different.
    geometry: plume_pixels.geometry(), // Use the plume_pixels geometry (might be large)
    scale: 750,
    maxPixels: 1e9
  }).getInfo();

  // Create a proper centroid for the plume areas
  const plume_regions = plume_pixels.mask(plume_pixels).focal_mode(1, 'square', 'pixels', 1).connectedComponents({
    connectedness: ee.Image.connectedComponents.EIGHT,
    maxSize: 1024
  });

  const plume_stats = plume_regions.reduceRegion({
    reducer: ee.Reducer.mean().group(1, 'label'), // Group by label to find multiple centroids if any
    geometry: etna_area,
    scale: 750,
    maxPixels: 1e9
  });

  const etna_lon = etna.coordinates().get(0).getInfo();

  // Calculate the weighted centroid of the plume
  let plume_weighted_centroid = plume_pixels.updateMask(plume_pixels.gt(0)).reduceRegion({
    reducer: ee.Reducer.centroid(),
    geometry: etna_area,
    scale: 750,
    maxPixels: 1e9
  }).getInfo();

  if (plume_weighted_centroid === null) {
      console.log("C3"); // Centroid calculation failed
      return;
  }

  const plume_centroid_lon = plume_weighted_centroid.centroid_lon;
  const plume_centroid_lat = plume_weighted_centroid.centroid_lat;

  if (plume_centroid_lon === null || plume_centroid_lat === null) {
    console.log("C3"); // Centroid calculation failed
    return;
  }

  console.log(`Etna Lon: ${etna_lon.toFixed(2)}, Plume Centroid Lon: ${plume_centroid_lon.toFixed(2)}`);

  // Compare the longitude of the plume centroid with Etna's longitude
  // A negative difference (plume_centroid_lon < etna_lon) means it's to the west.
  // We need a significant difference, not just tiny pixel variations.
  const min_west_displacement = -0.05; // ~5km west in longitude at this latitude

  if (plume_centroid_lon < etna_lon + min_west_displacement) {
    console.log("A"); // Plume went to the western side
  } else {
    console.log("B"); // Plume did not go to the western side (or was centered over Etna/went east)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
